            {"id": "upstream0001", "label": "up", "status": "pending", "model": "m", "cwd": _td3},
            {"id": "cancelme0001", "label": "never-ran", "status": "pending",
             "model": "m", "cwd": _td3, "verify": "true", "after": "upstream0001"},
